// Generated by scripts/sync-arbiter-mod-vendor.mjs from clients/arbiter-claude/src/tool-normalize.ts. Do not edit. Run the script.
// Canonical tool-name normalization (plan §4.4).
//
// Claude Code names MCP tools `mcp__<server>__<action>`. SCOPE-MCP keys classifications by
// `<platform>.<action>` (e.g. "github.create_pull_request") and the entity-approval resolver
// matches via bidirectional substring `includes`. We therefore emit a SINGLE normalized dotted
// string — never a candidate array. Passing an array makes the resolver treat each form as a
// separate tool and dump the non-matching one into `unresolved_tools`, forcing a spurious
// ASK even on an approved tool (plan F2, verified against entity-approval-resolver.ts).

const MCP_PREFIX = 'mcp__';
const MCP_SEP = '__';

export interface NormalizedTool {
  /** Dotted name to send to the server, e.g. "github.create_pull_request". For native tools, the raw name. */
  normalized: string;
  /** true when this is NOT an mcp__ tool (Bash/Edit/Write/Grep/etc.) — not gated in v1. */
  isNativeTool: boolean;
  /** MCP server segment when applicable, e.g. "github". */
  server?: string;
  /** MCP action segment when applicable, e.g. "create_pull_request" (kept verbatim). */
  action?: string;
}

export function normalizeToolName(rawToolName: string): NormalizedTool {
  if (!rawToolName.startsWith(MCP_PREFIX)) {
    return { normalized: rawToolName, isNativeTool: true };
  }
  const rest = rawToolName.slice(MCP_PREFIX.length);
  const sep = rest.indexOf(MCP_SEP);
  if (sep === -1) {
    // Malformed (e.g. "mcp__github" with no action). Treat the remainder as the server only.
    return { normalized: rest, isNativeTool: false, server: rest };
  }
  const server = rest.slice(0, sep);
  // Action keeps any further underscores verbatim (SCOPE ids are verbatim tool names).
  const action = rest.slice(sep + MCP_SEP.length);
  return { normalized: `${server}.${action}`, isNativeTool: false, server, action };
}
